o['totalText']);?></td><td><?php echo esc_html($o['detail']);?></td></tr><?php endforeach;?></tbody></table></div><div class="actions"><button class="btn" onclick="window.print()">Imprimir / Guardar PDF</button><a class="btn dark" target="_blank" href="https://wa.me/?text=<?php echo rawurlencode('Hola, te compartimos el presupuesto '.$s['number'].': '.home_url('/presupuesto/'.get_post_meta($posts[0]->ID,'_fbpos_token',true).'/'));?>">Compartir por WhatsApp</a></div><div class="foot">Precios y disponibilidad sujetos a confirmación al momento de concretar la compra. <?php echo esc_html($s['note']);?></div></div><?php if(!empty($_GET['print'])):?><script>window.addEventListener('load',()=>window.print())</script><?php endif;?></body></html>
